    REFERENCES public.scan_pages (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_scan_sentences_page_id
    ON public.scan_sentences(page_id);


ALTER TABLE IF EXISTS public.scan_sentences
    ADD CONSTRAINT fk_scan_sentences_scan FOREIGN KEY (scan_id)
    REFERENCES public.scans (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE CASCADE;
CREATE INDEX IF NOT EXISTS idx_scan_sentences_scan_id
    ON public.scan_sentences(scan_id);


ALTER TABLE IF EXISTS public.scan_sentences
    ADD CONSTRAINT fk_scan_sentences_section FOREIGN KEY (section_id)
    REFERENCES public.scan_sections (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE SET NULL;


ALTER TABLE IF EXISTS public.scans
    ADD CONSTRAINT fk_scans_owner FOREIGN KEY (owner_id)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS idx_scans_owner_id
    ON public.scans(owner_id);


ALTER TABLE IF EXISTS public.scans
    ADD CONSTRAINT fk_scans_reviewed_by_users FOREIGN KEY (reviewed_by)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE NO ACTION;


ALTER TABLE IF EXISTS public.scans
    ADD CONSTRAINT fk_scans_scanned_by FOREIGN KEY (scanned_by)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS idx_scans_scanned_by
    ON public.scans(scanned_by);


ALTER TABLE IF EXISTS public.student_officer_profiles
    ADD CONSTRAINT fk_student_profile_user FOREIGN KEY (user_id)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS student_officer_profiles_user_id_key
    ON public.student_officer_profiles(user_id);


ALTER TABLE IF EXISTS public.system_settings
    ADD CONSTRAINT fk_system_settings_user FOREIGN KEY (updated_by)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE SET NULL;


ALTER TABLE IF EXISTS public.user_roles
    ADD CONSTRAINT fk_user_roles_assigned_by FOREIGN KEY (assigned_by)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE SET NULL;


ALTER TABLE IF EXISTS public.user_roles
    ADD CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id)
    REFERENCES public.roles (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;


ALTER TABLE IF EXISTS public.user_roles
    ADD CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id)
    REFERENCES public.users (id) MATCH SIMPLE
    ON UPDATE NO ACTION
    ON DELETE RESTRICT;

END;